    explicitSnapshot ? { savedWalls: savedProject?.walls ?? [] } : {});
  const poles = poleCalc.poles;
  const wallCaps = calcWallCaps(project.wall_caps, inventory,
    explicitSnapshot ? { savedCaps: savedProject?.wall_caps ?? [] } : {});

